mapper.select:
select t.heartbeat_time,t.heartbeat_time heartbeatTime,t.impl_bean,t.impl_bean
implBean,t.machine_id,t.machine_id machineId,t.machine_code,t.machine_code
machineCode,t.energy_price,t.energy_price energyPrice,t.rule_id,t.rule_id
ruleId,t.community_id,t.community_id communityId,t.charge_type,t.charge_type chargeType,
t.machine_name,t.machine_name machineName,cmf.factory_name factoryName,t.create_time createTime,
cr.rule_name ruleName,td.name chargeTypeName,t.monitor_id monitorId,t.monitor_name monitorName,
count(cmp.port_id) portCount,
sum(case when cmp.state is not null and cmp.state != 'FREE' then 1 else 0 end) usingPortCount
from charge_machine t
left join charge_rule cr on t.rule_id = cr.rule_id and cr.status_cd = '0'
left join charge_machine_factory cmf on t.impl_bean = cmf.factory_id and cmf.status_cd = '0'
left join charge_machine_port cmp on t.machine_id = cmp.machine_id  and cmp.status_cd = '0'
left join t_dict td on td.status_cd = t.charge_type and td.table_name = 'charge_machine' and td.table_columns = 'charge_type'
where 1 =1

    and t.heartbeat_time= #{heartbeatTime}


    and t.impl_bean= #{implBean}


    and t.machine_id= #{machineId}


    and t.machine_code= #{machineCode}


    and t.energy_price= #{energyPrice}


    and t.rule_id= #{ruleId}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.community_id in

        #{item}



    and t.machine_name= #{machineName}


    and t.charge_type= #{chargeType}

group by t.heartbeat_time,t.impl_bean,t.machine_id,t.machine_code,t.energy_price,t.rule_id,t.community_id,t.charge_type,t.machine_name,
cmf.factory_name ,t.create_time,cr.rule_name,td.name,t.monitor_id,t.monitor_name
order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update charge_machine t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    , t.heartbeat_time= #{heartbeatTime}


    , t.impl_bean= #{implBean}


    , t.machine_code= #{machineCode}


    , t.energy_price= #{energyPrice}


    , t.rule_id= #{ruleId}



    , t.machine_name= #{machineName}


    , t.charge_type= #{chargeType}


    , t.monitor_id= #{monitorId}


    , t.monitor_name= #{monitorName}

where 1=1

    and t.machine_id= #{machineId}


    and t.community_id= #{communityId}

mapper.select:
select count(1) count
from charge_machine t
where 1 =1

    and DATE_ADD(t.heartbeat_time, INTERVAL 2 MINUTE) < #{heartbeatTime}


    and t.impl_bean= #{implBean}


    and t.machine_id= #{machineId}


    and t.machine_code= #{machineCode}


    and t.energy_price= #{energyPrice}


    and t.rule_id= #{ruleId}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.community_id in

        #{item}



    and t.machine_name= #{machineName}


    and t.charge_type= #{chargeType}
